import math

def grad_of(spec, values):
    grads = {k: 0.0 for k in values}

    def fwd(node):
        if isinstance(node, str):
            return values[node]
        if isinstance(node, (int, float)):
            return float(node)
        op = node[0]
        if op == "add":
            return fwd(node[1]) + fwd(node[2])
        if op == "mul":
            return fwd(node[1]) * fwd(node[2])
        if op == "exp":
            return math.exp(fwd(node[1]))
        if op == "pow":
            return fwd(node[1]) ** node[2]
        raise ValueError(op)

    def back(node, g):
        if isinstance(node, str):
            grads[node] += g
            return
        if isinstance(node, (int, float)):
            return
        op = node[0]
        if op == "add":
            back(node[1], g)
            back(node[2], g)
        elif op == "mul":
            back(node[1], g * fwd(node[2]))
            back(node[2], g * fwd(node[1]))
        elif op == "exp":
            back(node[1], g * math.exp(fwd(node[1])))
        elif op == "pow":
            k = node[2]
            back(node[1], g * k * fwd(node[1]) ** (k - 1))

    back(spec, 1.0)
    return grads

